import json, sys, re
path = sys.argv[1]
mode = sys.argv[2]  # user | grep
pat = re.compile(sys.argv[3], re.I) if len(sys.argv) > 3 else None
for i, line in enumerate(open(path)):
    try:
        d = json.loads(line)
    except Exception:
        continue
    t = d.get('type')
    if t not in ('user', 'assistant'):
        continue
    if d.get('isSidechain'):
        continue
    c = d.get('message', {}).get('content')
    texts = []
    if isinstance(c, str):
        texts.append(c)
    elif isinstance(c, list):
        for p in c:
            if isinstance(p, dict) and p.get('type') == 'text':
                texts.append(p.get('text', ''))
    txt = '\n'.join(texts).strip()
    if not txt:
        continue
    ts = d.get('timestamp', '')[:19]
    if mode == 'user' and t == 'user':
        if txt.startswith('<system-reminder') and len(txt) > 3000:
            continue
        print(f'[{i}] {ts} USER: {txt[:1500]}\n')
    elif mode == 'grep' and pat and pat.search(txt):
        for m in pat.finditer(txt):
            s = max(0, m.start() - 400)
            e = min(len(txt), m.end() + 400)
            print(f'[{i}] {ts} {t.upper()}: ...{txt[s:e]}...\n')
            break

