limit = int(sys.argv[4]) if len(sys.argv) > 4 else 2500
for i, line in enumerate(open(path)):
    if i < start or i > end:
        continue
    try:
        d = json.loads(line)
    except Exception:
        continue
    t = d.get('type')
    if t not in ('user', 'assistant') or d.get('isSidechain'):
        continue
    c = d.get('message', {}).get('content')
    if isinstance(c, str):
        txt = c
    else:
        txt = '\n'.join(p.get('text', '') for p in (c or []) if isinstance(p, dict) and p.get('type') == 'text')
    txt = txt.strip()
    if txt:
        print(f'[{i}] {d.get("timestamp","")[:19]} {t.upper()}: {txt[:limit]}\n')

