634	void ProjectAutosave::tick()
635	{
636	    try {
637	        adopt_project();
638	        if (!settle(false) && m_worker.valid())
639	            return;
640	        observe_document_change();
641	        const auto now = Clock::now();
642	        if (now < m_next_probe)
643	            return;
644	        m_next_probe = now + kProbeInterval;
645	        if (m_plater.model().objects.empty() && m_store->head_id().empty() &&
646	            m_persistence.document().doc_revision() <= 1) {
647	            m_state = State::Saved;
648	            return;
649	        }
650	        const std::string model_input = observed_input();
651	        if (model_input != m_seen_model_input) {
652	            m_seen_model_input = model_input;
653	            m_last_edit = now;
654	            m_state = State::Saving;
655	        }
656	        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
657	        const bool document_due = document_pending &&
658	            (now - m_last_semantic_edit >= kEditQuietPeriod ||
659	             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
660	        // A continuously edited model must not starve the current document.
661	        // Model capture also publishes the document, so a ready model still
662	        // takes precedence until the document's maximum delay is reached.
663	        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
664	            persist_document(false);
665	            return;
666	        }
667	        const bool model_pending = m_store->head_id().empty() || model_input != m_last_capture_input;
668	        const bool held          = model_pending && m_capture_hold && m_capture_hold();
669	        if (model_pending && !held) {
670	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
671	            if (canvas == nullptr || !canvas->is_initialized() ||
672	                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
673	                now - m_last_edit < kEditQuietPeriod)
674	                return;
675	            capture(false);
676	        } else if (document_pending) {
677	            if (!document_due)
678	                return;
679	            persist_document(false);
680	        } else if (!held) {
681	            m_state = State::Saved;
682	            m_first_semantic_edit.reset();
683	        }
684	    } catch (const std::exception& error) {
685	        fail(error.what());
686	    }
687	}
