TEST_CASE("a printer switch on a blank project saves no before-version", "[tools][versions]")
{
    Harness h;
    Workspace::ConfiguredPrinter configured;
    configured.preset           = "A1 mini 0.4";
    configured.model            = "N1";
    configured.nozzle_diameters = {0.4};
    configured.plate_type       = "Textured PEI Plate";
    configured.filaments        = {{"Generic PLA", "PLA"}};
    h.workspace.set_configured_printer_for_testing(configured);
    h.workspace.set_setup_for_testing("0.20mm Standard", {"Textured PEI Plate"}, {{"Generic PLA", "PLA"}});
    h.workspace.set_presets_for_testing(Workspace::PresetKind::Printer, {{"A1 mini 0.4"}, {"A1 mini 0.2"}});

    int  pinned = 0;
    int  boundaries = 0;
    bool blank = true;
    h.coordinator.set_version_callbacks(
        [&pinned](const ToolActivity&) { ++pinned; return std::string("v-before"); },
        [](const ToolActivity&, const std::string&) {},
        [&blank] { return blank; });
    h.coordinator.set_document_boundary_callback([&boundaries](const ToolActivity&) { ++boundaries; });
    const auto run = [&h](const std::string& preset) {
        const std::string id = h.coordinator.submit({"printer_setup", json{{"printerPreset", preset}}.dump()}, "m-1").action_id;
        h.pump_to_completion(id);
        CHECK(h.coordinator.find(id)->state == ToolState::Succeeded);
    };

    run("A1 mini 0.2");
    CHECK(pinned == 0);
    CHECK(boundaries == 1);

    // Anything else that changes the project keeps the state it can go back to.
    const std::string duplicate = h.coordinator.submit(h.duplicate_cube_request(), "m-2").action_id;
    h.pump_to_completion(duplicate);
    CHECK(pinned == 1);

    // With the person's work in the project, a switch keeps a version too.
    blank = false;
    run("A1 mini 0.4");
    CHECK(pinned == 2);
}

