148	// The folders in the projects folder, or nothing when that folder exists but
149	// cannot be listed (its permissions, a storage fault): callers say so rather
150	// than treat it as holding no projects. No projects folder yet is a new
151	// installation with none.
152	std::optional<std::vector<std::filesystem::path>> project_folders(const std::filesystem::path& root)
153	{
154	    std::vector<std::filesystem::path> folders;
155	    std::error_code error;
156	    // exists() clears the error for a path that is not there; is_directory()
157	    // reports it as an error.
158	    if (!std::filesystem::exists(root, error) && !error)
159	        return folders;
160	    std::filesystem::directory_iterator it(root, error);
161	    for (const std::filesystem::directory_iterator end; !error && it != end; it.increment(error))
162	        folders.push_back(it->path());
163	    if (error) {
164	        BOOST_LOG_TRIVIAL(error) << "Local projects could not be listed: " << root.string() << ": " << error.message();
165	        return std::nullopt;
166	    }
167	    return folders;
168	}
