170	// Whether a project's document holds anything the person would want back. The
171	// empty project OrcaSlicer always keeps open stays in memory until it does.
172	// None of these count: a preset choice, which the app's own settings keep; a
173	// chat with no messages and its model; tool activity and work in progress,
174	// because a tool that changes the project first saves through pin_current and
175	// a chat's own activity comes with its messages.
176	bool holds_work(const nlohmann::json& state)
177	{
178	    const auto recorded = [&state](const char* key) { return !state.value(key, nlohmann::json::array()).empty(); };
179	    const auto changes  = state.value("changes", nlohmann::json::array());
180	    const auto chats    = state.value("conversations", nlohmann::json::array());
181	    return recorded("attachments") || recorded("gcodes") || recorded("regions") || state.contains("calibration") ||
182	           !state.value("draft", "").empty() ||
183	           std::any_of(changes.begin(), changes.end(), [](const nlohmann::json& change) { return change.value("kind", "") != "preset"; }) ||
184	           std::any_of(chats.begin(), chats.end(), [](const nlohmann::json& chat) { return !chat.value("messages", nlohmann::json::array()).empty(); });
185	}
