187	bool authored_head(const std::filesystem::path& project)
188	{
189	    std::ifstream head(project / "HEAD", std::ios::binary);
190	    std::string content((std::istreambuf_iterator<char>(head)), std::istreambuf_iterator<char>());
191	    if (content.empty()) return false;
192	    const std::string id = nlohmann::json::parse(content).at("current").get<std::string>();
193	    const auto version = project / "versions" / id;
194	    std::ifstream manifest_file(version / "manifest.json", std::ios::binary);
195	    const auto manifest = nlohmann::json::parse(manifest_file);
196	    if (!manifest.at("objects").empty())
197	        return true;
198	    const auto current_path = project / "current-state.json";
199	    if (!std::filesystem::exists(current_path))
200	        return false;
201	    std::ifstream current_file(current_path, std::ios::binary);
202	    return holds_work(nlohmann::json::parse(current_file).at("state"));
203	}
