205	// The MD5 of a file's content; empty when it cannot be read.
206	std::string file_digest(const std::filesystem::path& path)
207	{
208	    try {
209	        std::string name = path.u8string(), digest;
210	        return std::filesystem::is_regular_file(path) && bbl_calc_md5(name, digest) ? digest : std::string();
211	    } catch (const std::exception&) {
212	        return {};
213	    }
214	}
