216	bool same_source_path(const std::filesystem::path& first, const std::filesystem::path& second)
217	{
218	    if (first.empty() || second.empty()) return false;
219	    std::error_code error;
220	    if (std::filesystem::exists(first, error) && !error &&
221	        std::filesystem::exists(second, error) && !error &&
222	        std::filesystem::equivalent(first, second, error) && !error)
223	        return true;
224	    error.clear();
225	    const auto normalized_first = std::filesystem::weakly_canonical(first, error);
226	    if (error) return false;
227	    error.clear();
228	    const auto normalized_second = std::filesystem::weakly_canonical(second, error);
229	    if (error) return false;
230	#ifdef _WIN32
231	    std::wstring left = normalized_first.wstring(), right = normalized_second.wstring();
232	    std::transform(left.begin(), left.end(), left.begin(), [](wchar_t value) { return std::towlower(value); });
233	    std::transform(right.begin(), right.end(), right.begin(), [](wchar_t value) { return std::towlower(value); });
234	    return left == right;
235	#else
236	    return normalized_first == normalized_second;
237	#endif
238	}
