262	// Managed checkpoints keep their captured settings; ordinary 3MF exports keep Orca's
263	// actual preset-difference list. Rewrite only the unpublished backup archive.
264	void protect_saved_settings(const std::filesystem::path& metadata)
265	{
266	    constexpr const char* entry = "Metadata/project_settings.config";
267	    mz_zip_archive source, target;
268	    mz_zip_zero_struct(&source);
269	    mz_zip_zero_struct(&target);
270	    if (!open_zip_reader(&source, metadata.u8string()))
271	        throw std::runtime_error("Could not read captured project metadata");
272	
273	    bool target_open = false;
274	    auto rewritten = metadata;
275	    rewritten += ".rewrite";
276	    try {
277	        const int entry_index = mz_zip_reader_locate_file(&source, entry, nullptr, 0);
278	        if (entry_index < 0)
279	            throw std::runtime_error("Captured project settings are missing");
280	        size_t size = 0;
281	        void* data = mz_zip_reader_extract_file_to_heap(&source, entry, &size, 0);
282	        if (!data)
283	            throw std::runtime_error("Could not read captured project settings");
284	        std::string original(static_cast<const char*>(data), size);
285	        mz_free(data);
286	
287	        auto settings = nlohmann::json::parse(original);
288	        const auto& colours = settings.at("filament_colour");
289	        if (!colours.is_array() || colours.empty())
290	            throw std::runtime_error("Captured project has no filament settings");
291	        std::vector<std::string> keys;
292	        for (auto it = settings.begin(); it != settings.end(); ++it)
293	            if (it.key() != "version" && it.key() != "name" && it.key() != "from" &&
294	                it.key() != "different_settings_to_system")
295	                keys.push_back(it.key());
296	        const std::string protected_keys = escape_strings_cstyle(keys);
297	        settings["different_settings_to_system"] =
298	            std::vector<std::string>(colours.size() + 2, protected_keys);
299	        const std::string replacement = settings.dump(1, '\t') + '\n';
300	
301	        if (!open_zip_writer(&target, rewritten.u8string()))
302	            throw std::runtime_error("Could not rewrite captured project metadata");
303	        target_open = true;
304	        for (mz_uint index = 0; index < mz_zip_reader_get_num_files(&source); ++index) {
305	            const bool added = int(index) == entry_index ?
306	                mz_zip_writer_add_mem(&target, entry, replacement.data(), replacement.size(), MZ_DEFAULT_COMPRESSION) :
307	                mz_zip_writer_add_from_zip_reader(&target, &source, index);
308	            if (!added)
309	                throw std::runtime_error("Could not copy captured project metadata entry");
310	        }
311	        if (!mz_zip_writer_finalize_archive(&target))
312	            throw std::runtime_error("Could not finalize captured project metadata");
313	        target_open = false;
314	        if (!close_zip_writer(&target))
315	            throw std::runtime_error("Could not close rewritten project metadata");
316	        if (!close_zip_reader(&source))
317	            throw std::runtime_error("Could not close captured project metadata");
318	#ifdef _WIN32
319	        // This archive is still unpublished staging data; Windows cannot rename over it.
320	        std::filesystem::remove(metadata);
321	#endif
322	        std::filesystem::rename(rewritten, metadata);
323	    } catch (...) {
324	        if (target_open) close_zip_writer(&target);
325	        if (source.m_zip_mode == MZ_ZIP_MODE_READING) close_zip_reader(&source);
326	        std::error_code ignored;
327	        std::filesystem::remove(rewritten, ignored);
328	        throw;
329	    }
330	}
