381	std::string ProjectAutosave::observed_input() const
382	{
383	    // Only native printable project state belongs in checkpoint detection.
384	    // Conversation, plans, intent, audit, and print facts are durable in the
385	    // current document and cannot force a model export.
386	    // The scan touches identities, timestamps and small metadata, never mesh
387	    // triangles or Orca's 3MF writer.
388	    std::ostringstream out;
389	    out << std::setprecision(17) << m_event_sequence << ';';
390	    append_text(out, m_persistence.document().project_id());
391	    append_text(out, m_plater.get_project_name().ToUTF8().data());
392	    append_text(out, m_plater.get_project_filename(".3mf").ToUTF8().data());
393	    const Model& model = m_plater.model();
394	    out << model.id().id << ';' << model.objects.size() << ';';
395	    if (model.model_info) {
396	        append_text(out, model.model_info->cover_file);
397	        append_text(out, model.model_info->description);
398	        append_text(out, model.model_info->model_name);
399	    }
400	    for (const auto& [plate_index, codes] : model.plates_custom_gcodes) {
401	        out << plate_index << ',' << int(codes.mode) << ',' << codes.gcodes.size() << ';';
402	        for (const auto& code : codes.gcodes) {
403	            out << code.print_z << ',' << int(code.type) << ',' << code.extruder << ';';
404	            append_text(out, code.color);
405	            append_text(out, code.extra);
406	        }
407	    }
408	    for (const ModelObject* object : model.objects) {
409	        out << object->id().id << ',' << object->printable << ','
410	            << static_cast<const ModelConfig&>(object->config).timestamp()
411	            << ',' << object->layer_height_profile.timestamp() << ';';
412	        append_text(out, object->name);
413	        out << object->brim_points.size() << ';';
414	        for (const auto& point : object->brim_points)
415	            out << point.pos.x() << ',' << point.pos.y() << ',' << point.pos.z() << ',' << point.head_front_radius << ';';
416	        out << object->volumes.size() << ';';
417	        for (const ModelVolume* volume : object->volumes) {
418	            out << volume->id().id << ',' << volume->mesh_ptr().get() << ',' << int(volume->type())
419	                << ',' << static_cast<const ModelConfig&>(volume->config).timestamp()
420	                << ',' << volume->supported_facets.timestamp()
421	                << ',' << volume->seam_facets.timestamp() << ',' << volume->mmu_segmentation_facets.timestamp()
422	                << ',' << volume->fuzzy_skin_facets.timestamp() << ';';
423	            append_text(out, volume->name);
424	            append_text(out, volume->material_id());
425	            append_transform(out, volume->get_matrix());
426	        }
427	        out << object->instances.size() << ';';
428	        for (const ModelInstance* instance : object->instances) {
429	            out << instance->id().id << ',' << instance->printable << ',' << instance->auto_drop
430	                << ',' << instance->arrange_order << ';';
431	            append_transform(out, instance->get_matrix());
432	        }
433	    }
434	    PartPlateList& plates = m_plater.get_partplate_list();
435	    out << plates.get_plate_count() << ';';
436	    for (int index = 0; index < plates.get_plate_count(); ++index) {
437	        PartPlate* plate = plates.get_plate(index);
438	        out << plate->id().id << ',' << int(plate->get_bed_type()) << ',' << plate->is_locked()
439	            << ',' << int(plate->get_filament_map_mode()) << ';';
440	        append_text(out, plate->get_plate_name());
441	        for (int filament : plate->get_filament_maps()) out << filament << ',';
442	        out << ';';
443	        append_config(out, *plate->config());
444	    }
445	    if (const PresetBundle* presets = wxGetApp().preset_bundle)
446	        append_config(out, presets->full_config_secure());
447	    return out.str();
448	}
