450	void ProjectAutosave::trim_history()
451	{
452	    try {
453	        std::set<std::string> live_attachments;
454	        for (const auto& attachment : m_persistence.document().attachments())
455	            if (!attachment.stored_name.empty())
456	                live_attachments.insert(attachment.relative_path());
457	        m_store->prune(kMaxVersions, kMaxBytes, live_attachments);
458	        m_warning.clear();
459	    } catch (const std::exception& error) {
460	        // The current head was already committed. A retention failure leaves
461	        // extra old data and must not misreport the current project as unsaved.
462	        m_warning = std::string("Local history cleanup failed: ") + error.what();
463	        BOOST_LOG_TRIVIAL(warning) << m_warning;
464	    }
465	}
466	
467	bool ProjectAutosave::settle(bool wait)
468	{
469	    if (!m_worker.valid())
470	        return true;
471	    if (!wait && m_worker.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
472	        return false;
473	    try {
474	        m_worker.get();
475	        if (m_worker_kind == WorkerKind::Model) {
476	            m_committed_head = m_store->head_id();
477	            m_last_capture_input = std::move(m_inflight_capture_input);
478	            m_seen_model_input = m_last_capture_input;
479	            trim_history();
480	        }
481	        if (m_worker_kind == WorkerKind::Document)
482	            m_committed_semantic_revision = m_inflight_semantic_revision;
483	        m_worker_kind = WorkerKind::None;
484	        if (m_seen_semantic_revision == m_committed_semantic_revision)
485	            m_first_semantic_edit.reset();
486	        m_error.clear();
487	        // A main-thread edit may have landed while the worker wrote the
488	        // frozen revision. Probe again before saying the current model is saved.
489	        m_state = State::Saving;
490	        m_next_probe = Clock::now();
491	        return true;
492	    } catch (const std::exception& error) {
493	        m_worker_kind = WorkerKind::None;
494	        m_inflight_capture_input.clear();
495	        fail(error.what());
496	    } catch (...) {
497	        m_worker_kind = WorkerKind::None;
498	        m_inflight_capture_input.clear();
499	        fail("project version writer failed");
500	    }
501	    return false;
502	}
