504	void ProjectAutosave::adopt_project()
505	{
506	    m_persistence.resolve_pending_boundary();
507	    const std::string id = m_persistence.document().project_id();
508	    if (m_store && m_store->project_id() == id)
509	        return;
510	    settle(true);
511	    m_store.reset();
512	    if (id.empty())
513	        throw std::runtime_error("open project has no identity");
514	    m_store = std::make_unique<ProjectVersionStore>(m_root, id);
515	    m_last_capture_input.clear();
516	    m_seen_model_input.clear();
517	    m_inflight_capture_input.clear();
518	    m_committed_head = m_store->head_id();
519	    m_committed_semantic_revision = m_committed_head.empty() ? 0 : m_persistence.document().doc_revision();
520	    m_seen_semantic_revision = m_persistence.document().doc_revision();
521	    m_last_semantic_edit = Clock::now();
522	    m_first_semantic_edit = m_seen_semantic_revision != m_committed_semantic_revision ?
523	        std::optional<Clock::time_point>(m_last_semantic_edit) : std::nullopt;
524	    const auto versions = m_store->history();
525	    m_project_name = versions.empty() ? std::string() : versions.back().project_name;
526	    m_opened_from = versions.empty() ? std::string() : versions.back().opened_from;
527	    m_opened_digest = versions.empty() ? std::string() : versions.back().opened_digest;
528	    if (const std::string file = m_plater.get_project_filename(".3mf").ToUTF8().data(); versions.empty() && !file.empty()) {
529	        m_opened_from = file;
530	        m_opened_digest = file_digest(std::filesystem::u8path(file));
531	    }
532	    m_revision = 0;
533	    for (const auto& version : versions)
534	        m_revision = std::max(m_revision, version.revision);
535	    m_state = State::Saving;
536	    m_next_probe = Clock::now();
537	}
