539	bool ProjectAutosave::capture(bool wait_for_commit)
540	{
541	    if (!m_store)
542	        return false;
543	    std::filesystem::path metadata;
544	    try {
545	        const std::string id = ProjectVersionStore::new_id();
546	        metadata = m_store->pending_metadata_path(id);
547	        ++m_capture_attempts;
548	        const int result = m_plater.export_3mf(boost_path(metadata),
549	                                                SaveStrategy::Backup | SaveStrategy::Silence);
550	        if (result < 0)
551	            throw std::runtime_error("OrcaSlicer could not capture project metadata");
552	        protect_saved_settings(metadata);
553	        const wxString source = m_plater.get_project_filename(".3mf");
554	        auto frozen = m_store->freeze(m_plater.model(), id, ++m_revision, m_persistence.document().dump(),
555	                                      source.ToUTF8().data(), m_persistence.timestamp());
556	        const auto& changes = m_persistence.document().changes();
557	        if (!changes.empty())
558	            frozen.version.change_seq = changes.back().seq;
559	        const auto semantic_revision = m_persistence.document().doc_revision();
560	        m_committed_semantic_revision = semantic_revision;
561	        if (m_seen_semantic_revision == semantic_revision)
562	            m_first_semantic_edit.reset();
563	        const std::string plater_name(m_plater.get_project_name().ToUTF8());
564	        const std::string untitled(_L("Untitled").ToUTF8());
565	        frozen.version.project_name = m_project_name.empty() ? plater_name : m_project_name;
566	        // A project with no name yet takes its first object's. One the store
567	        // already named keeps it: a reopened project's Orca name reads
568	        // Untitled, and its next version must not rename it.
569	        if ((m_project_name.empty() || m_project_name == untitled) && (plater_name.empty() || plater_name == untitled) &&
570	            !m_plater.model().objects.empty())
571	            frozen.version.project_name = std::filesystem::u8path(m_plater.model().objects.front()->name).stem().u8string();
572	        m_project_name = frozen.version.project_name;
573	        // A project adopted before Orca named its file gets it with its first
574	        // version.
575	        if (m_opened_from.empty() && m_store->head_id().empty() && !source.empty()) {
576	            m_opened_from   = source.ToUTF8().data();
577	            m_opened_digest = file_digest(std::filesystem::u8path(m_opened_from));
578	        }
579	        frozen.version.opened_from = m_opened_from;
580	        frozen.version.opened_digest = m_opened_digest;
581	        if (m_store->unchanged(frozen)) {
582	            m_store->discard(frozen);
583	            m_last_capture_input = observed_input();
584	            m_seen_model_input = m_last_capture_input;
585	            m_seen_semantic_revision = semantic_revision;
586	            m_first_semantic_edit.reset();
587	            m_error.clear();
588	            m_state = State::Saved;
589	            return true;
590	        }
591	        m_state = State::Saving;
592	        if (wait_for_commit) {
593	            m_store->publish(std::move(frozen));
594	            m_committed_head = m_store->head_id();
595	            m_last_capture_input = observed_input();
596	            m_seen_model_input = m_last_capture_input;
597	            m_seen_semantic_revision = semantic_revision;
598	            m_first_semantic_edit.reset();
599	            trim_history();
600	            m_error.clear();
601	            m_state = State::Saved;
602	        } else {
603	            m_inflight_capture_input = observed_input();
604	            m_seen_model_input = m_inflight_capture_input;
605	            m_inflight_semantic_revision = semantic_revision;
606	            m_worker_kind = WorkerKind::Model;
607	            m_worker = std::async(std::launch::async, [this, frozen = std::move(frozen)]() mutable {
608	                m_store->publish(std::move(frozen));
609	            });
610	        }
611	        return true;
612	    } catch (const std::exception& error) {
613	        m_worker_kind = WorkerKind::None;
614	        if (!metadata.empty())
615	            std::filesystem::remove_all(metadata.parent_path());
616	        fail(error.what());
617	    }
618	    return false;
619	}
