621	bool ProjectAutosave::persist_document(bool wait_for_commit)
622	{
623	    if (!m_store)
624	        return false;
625	    try {
626	        const std::string state = m_persistence.document().dump();
627	        const auto revision = m_persistence.document().doc_revision();
628	        m_state = State::Saving;
629	        if (wait_for_commit) {
630	            m_store->publish_document(state);
631	            m_committed_semantic_revision = revision;
632	            m_seen_semantic_revision = revision;
633	            m_first_semantic_edit.reset();
634	            m_error.clear();
635	            m_state = State::Saved;
636	        } else {
637	            m_inflight_semantic_revision = revision;
638	            m_worker_kind = WorkerKind::Document;
639	            m_worker = std::async(std::launch::async, [this, state] {
640	                m_store->publish_document(state);
641	            });
642	        }
643	        return true;
644	    } catch (const std::exception& error) {
645	        m_worker_kind = WorkerKind::None;
646	        fail(error.what());
647	        return false;
648	    }
649	}
