651	void ProjectAutosave::tick()
652	{
653	    try {
654	        adopt_project();
655	        if (!settle(false) && m_worker.valid())
656	            return;
657	        observe_document_change();
658	        const auto now = Clock::now();
659	        if (now < m_next_probe)
660	            return;
661	        m_next_probe = now + kProbeInterval;
662	        if (blank_with_no_work()) {
663	            m_state = State::Saved;
664	            return;
665	        }
666	        const std::string model_input = observed_input();
667	        if (model_input != m_seen_model_input) {
668	            m_seen_model_input = model_input;
669	            m_last_edit = now;
670	            m_state = State::Saving;
671	        }
672	        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
673	        const bool document_due = document_pending &&
674	            (now - m_last_semantic_edit >= kEditQuietPeriod ||
675	             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
676	        // A continuously edited model must not starve the current document.
677	        // Model capture also publishes the document, so a ready model still
678	        // takes precedence until the document's maximum delay is reached.
679	        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
680	            persist_document(false);
681	            return;
682	        }
683	        const bool model_pending = m_store->head_id().empty() || model_input != m_last_capture_input;
684	        const bool held          = model_pending && m_capture_hold && m_capture_hold();
685	        if (model_pending && !held) {
686	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
687	            if (canvas == nullptr || !canvas->is_initialized() ||
688	                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
689	                now - m_last_edit < kEditQuietPeriod)
690	                return;
691	            capture(false);
692	        } else if (document_pending) {
693	            if (!document_due)
694	                return;
695	            persist_document(false);
696	        } else if (!held) {
697	            m_state = State::Saved;
698	            m_first_semantic_edit.reset();
699	        }
700	    } catch (const std::exception& error) {
701	        fail(error.what());
702	    }
703	}
