705	std::optional<std::vector<ProjectAutosave::ManagedProject>> ProjectAutosave::projects()
706	{
707	    settle(true);
708	    // Home can be opened before the first project switch. Render the current
709	    // project once here; the preview is independent of the frequent backups.
710	    ensure_current_preview();
711	    const auto folders = project_folders(m_root);
712	    if (!folders)
713	        return std::nullopt;
714	    std::vector<ManagedProject> result;
715	    for (const auto& folder : *folders) {
716	        try {
717	            // Inside the try: a project folder that cannot be read is skipped
718	            // like any other unavailable project, not the whole list.
719	            if (!std::filesystem::is_directory(folder) || !std::filesystem::exists(folder / "HEAD"))
720	                continue;
721	            if (!authored_head(folder))
722	                continue;
723	            const std::string id = folder.filename().string();
724	            const auto add = [&result, &folder, &id](const ProjectVersionStore::Version& version,
725	                                                     const Agent::ProjectStateDocument& document, bool readable) {
726	                const auto source = std::filesystem::u8path(version.source_path);
727	                const std::string name = !version.project_name.empty() ? version.project_name : source.stem().u8string();
728	                ManagedProject project{id, name, version.created_at, version.source_path, folder.u8string()};
729	                if (readable)
730	                    project.gcodes = document.gcode_records();
731	                try {
732	                    project.thumbnail_url = saved_preview(folder, version.id);
733	                    if (project.thumbnail_url.empty()) {
734	                        // A project whose latest version was never rendered
735	                        // here has no preview sidecar for it. Orca's original
736	                        // 3MF thumbnail keeps its Home card useful until the
737	                        // project is next opened and rendered locally.
738	                        project.thumbnail_url = source_preview(version.source_path);
739	                        if (!project.thumbnail_url.empty())
740	                            write_preview(folder, version.id, project.thumbnail_url);
741	                    }
742	                } catch (const std::exception& error) {
743	                    // A damaged preview must not hide an otherwise healthy
744	                    // local project from Home.
745	                    BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
746	                }
747	                result.push_back(std::move(project));
748	            };
749	            // The open project's document is the one in memory, which can be
750	            // ahead of the file by the last few seconds of edits.
751	            if (m_store && id == m_store->project_id()) {
752	                const auto versions = m_store->history();
753	                if (!versions.empty())
754	                    add(versions.back(), m_persistence.document(), true);
755	            } else {
756	                ProjectVersionStore other(m_root, id);
757	                const auto versions = other.history();
758	                Agent::ProjectStateDocument document;
759	                const bool readable = document.load(other.current_document()) == Agent::ProjectStateDocument::LoadResult::Loaded;
760	                if (!versions.empty())
761	                    add(versions.back(), document, readable);
762	            }
763	        } catch (const std::exception& error) {
764	            BOOST_LOG_TRIVIAL(warning) << "Managed project unavailable: " << folder.string() << ": " << error.what();
765	        }
766	    }
767	    std::sort(result.begin(), result.end(), [](const ManagedProject& a, const ManagedProject& b) {
768	        return a.updated_at > b.updated_at;
769	    });
770	    return result;
771	}
