779	std::optional<std::vector<ProjectAutosave::SourceMatch>> ProjectAutosave::projects_for_source(const std::filesystem::path& source) const
780	{
781	    if (source.empty())
782	        return std::vector<SourceMatch>{};
783	    std::optional<std::string> digest_now; // read once, when a match needs it
784	    const auto changed = [&](const std::string& digest) -> std::optional<bool> {
785	        if (digest.empty())
786	            return std::nullopt;
787	        if (!digest_now)
788	            digest_now = file_digest(source);
789	        return *digest_now != digest;
790	    };
791	    std::vector<std::pair<std::filesystem::file_time_type, SourceMatch>> matches;
792	    const auto folders = project_folders(m_root);
793	    if (!folders)
794	        return std::nullopt;
795	    for (const auto& folder : *folders) {
796	        try {
797	            // A project folder that cannot be read is skipped, as in projects().
798	            if (!std::filesystem::is_directory(folder) || !std::filesystem::is_regular_file(folder / "HEAD"))
799	                continue;
800	            std::ifstream head_file(folder / "HEAD", std::ios::binary);
801	            const std::string head((std::istreambuf_iterator<char>(head_file)), std::istreambuf_iterator<char>());
802	            if (head.empty()) continue;
803	            std::vector<std::string> versions;
804	            if (head.front() == '{')
805	                versions = nlohmann::json::parse(head).at("versions").get<std::vector<std::string>>();
806	            else {
807	                std::string version = head;
808	                if (!version.empty() && version.back() == '\n') version.pop_back();
809	                versions.push_back(std::move(version));
810	            }
811	            for (auto it = versions.rbegin(); it != versions.rend(); ++it) {
812	                if (it->empty() || it->find_first_of("/\\") != std::string::npos) continue;
813	                std::ifstream manifest_file(folder / "versions" / *it / "manifest.json", std::ios::binary);
814	                if (!manifest_file) continue;
815	                const nlohmann::json manifest = nlohmann::json::parse(manifest_file);
816	                if (same_source_path(source, std::filesystem::u8path(manifest.value("sourcePath", std::string()))) ||
817	                    same_source_path(source, std::filesystem::u8path(manifest.value("openedFrom", std::string())))) {
818	                    auto updated = std::filesystem::last_write_time(folder / "HEAD");
819	                    if (std::filesystem::is_regular_file(folder / "current-state.json"))
820	                        updated = std::max(updated, std::filesystem::last_write_time(folder / "current-state.json"));
821	                    matches.emplace_back(updated, SourceMatch{folder.filename().string(), manifest.value("projectName", std::string()),
822	                                                              false, changed(manifest.value("openedDigest", std::string()))});
823	                    break;
824	                }
825	            }
826	        } catch (const std::exception& error) {
827	            BOOST_LOG_TRIVIAL(warning) << "Local project source index unavailable: " << folder.string()
828	                                       << ": " << error.what();
829	        }
830	    }
831	    std::sort(matches.begin(), matches.end(), [](const auto& a, const auto& b) {
832	        return a.first != b.first ? a.first > b.first : a.second.id > b.second.id;
833	    });
834	    std::vector<SourceMatch> result;
835	    result.reserve(matches.size());
836	    for (const auto& [updated, match] : matches)
837	        result.push_back(match);
838	    const wxString     current_source = m_plater.get_project_filename(".3mf");
839	    const std::string& current_id     = m_persistence.document().project_id();
840	    const bool         ours           = m_store && m_store->project_id() == current_id;
841	    if (same_source_path(source, std::filesystem::u8path(current_source.ToUTF8().data())) ||
842	        (ours && same_source_path(source, std::filesystem::u8path(m_opened_from)))) {
843	        auto current = std::find_if(result.begin(), result.end(), [&](const SourceMatch& match) { return match.id == current_id; });
844	        if (current != result.end())
845	            std::rotate(result.begin(), current, current + 1);
846	        else if (!current_id.empty())
847	            result.insert(result.begin(), SourceMatch{current_id, project_name()});
848	        result.front().current = true;
849	        if (ours)
850	            result.front().changed = changed(m_opened_digest);
851	    }
852	    return result;
853	}
