864	bool ProjectAutosave::open_managed_project(const std::string& project_id)
865	{
866	    if (!save_now())
867	        return false;
868	    ensure_current_preview();
869	    if (m_store->project_id() == project_id)
870	        return true;
871	    const std::string previous_id = m_store->head_id();
872	    std::optional<ProjectVersionStore::Materialization> target_materialized;
873	    std::unique_ptr<ProjectVersionStore> target;
874	    bool replacement_started = false;
875	    const auto load = [this](const ProjectVersionStore::Materialization& materialized,
876	                             const ProjectVersionStore::Version& version) {
877	        m_plater.reset();
878	        m_plater.take_snapshot("Open local project", UndoRedo::SnapshotType::ProjectSeparator);
879	        auto strategy = LoadStrategy::Restore;
880	        if (materialized.empty)
881	            strategy = strategy | LoadStrategy::AllowEmpty;
882	        const auto loaded = load_managed_checkpoint(m_plater, materialized, strategy);
883	        if ((loaded.empty() && !materialized.empty) || (materialized.empty && !m_plater.model().objects.empty()))
884	            throw std::runtime_error("local project could not be restored");
885	        m_plater.set_project_filename(wxString::FromUTF8(version.source_path));
886	    };
887	    try {
888	        target = std::make_unique<ProjectVersionStore>(m_root, project_id);
889	        const auto versions = target->history();
890	        if (versions.empty() || versions.back().id != target->head_id())
891	            throw std::runtime_error("local project has no current version");
892	        target_materialized = target->materialize(target->head_id());
893	        replacement_started = true;
894	        load(*target_materialized, versions.back());
895	        m_persistence.adopt_managed_state(target_materialized->semantic_state);
896	        target->seed_from_live(m_plater.model());
897	        m_last_capture_input = observed_input();
898	        m_seen_model_input = m_last_capture_input;
899	        m_committed_semantic_revision = m_persistence.document().doc_revision();
900	        m_seen_semantic_revision = m_committed_semantic_revision;
901	        m_first_semantic_edit.reset();
902	        if (m_active_materialization && m_active_materialization_project == m_store->project_id()) {
903	            try {
904	                m_store->remove_materialization(*m_active_materialization);
905	            } catch (const std::exception& cleanup_error) {
906	                m_warning = std::string("Old project workspace could not be removed: ") + cleanup_error.what();
907	                BOOST_LOG_TRIVIAL(warning) << m_warning;
908	            }
909	        }
910	        m_store = std::move(target);
911	        m_project_name = versions.back().project_name;
912	        m_opened_from = versions.back().opened_from;
913	        m_opened_digest = versions.back().opened_digest;
914	        m_active_materialization = *target_materialized;
915	        m_active_materialization_project = project_id;
916	        m_committed_head = m_store->head_id();
917	        m_revision = 0;
918	        for (const auto& version : versions)
919	            m_revision = std::max(m_revision, version.revision);
920	        m_error.clear();
921	        m_state = State::Saved;
922	        m_next_probe = Clock::now() + kProbeInterval;
923	        return true;
924	    } catch (const std::exception& error) {
925	        const std::string reason = error.what();
926	        if (replacement_started) {
927	            try {
928	                const auto previous = m_store->materialize(previous_id);
929	                const auto versions = m_store->history();
930	                const auto old = std::find_if(versions.begin(), versions.end(), [&previous_id](const auto& version) {
931	                    return version.id == previous_id;
932	                });
933	                if (old == versions.end())
934	                    throw std::runtime_error("previous project version was not found");
935	                load(previous, *old);
936	                m_persistence.adopt_managed_state(previous.semantic_state);
937	                m_store->seed_from_live(m_plater.model());
938	                m_active_materialization = previous;
939	                m_active_materialization_project = m_store->project_id();
940	                if (target && target_materialized)
941	                    target->remove_materialization(*target_materialized);
942	            } catch (const std::exception& rollback_error) {
943	                fail(reason + "; previous project also failed to reload: " + rollback_error.what());
944	                return false;
945	            }
946	        }
947	        fail(reason);
948	        return false;
949	    }
950	}
951	
952	void ProjectAutosave::ensure_current_preview()
953	{
954	    if (!m_store || m_store->head_id().empty() || m_plater.model().objects.empty())
955	        return;
956	    try {
957	        const auto project = m_root / m_store->project_id();
958	        if (!saved_preview(project, m_store->head_id()).empty())
959	            return;
960	        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
961	        if (canvas == nullptr || !canvas->is_initialized() || m_plater.get_partplate_list().get_plate_count() == 0)
962	            return;
963	        ThumbnailData data;
964	        // Frame all model volumes, including objects on other plates.
965	        ThumbnailsParams params{{}, false, true, false, true, 0, false};
966	        canvas->render_thumbnail(data, 256, 256, params, Camera::EType::Ortho);
967	        if (!data.is_valid())
968	            return;
969	        const bool has_subject = [&data] {
970	            for (std::size_t pixel = 3; pixel < data.pixels.size(); pixel += 4)
971	                if (data.pixels[pixel] != 0)
972	                    return true;
973	            return false;
974	        }();
975	        if (!has_subject)
976	            return;
977	        const auto png = GCodeThumbnails::compress_thumbnail(data, GCodeThumbnailsFormat::PNG);
978	        if (!png || !png->data || png->size == 0 || png->size > kMaxPreviewBytes)
979	            return;
980	        write_preview(project, m_store->head_id(),
981	                      "data:image/png;base64," + base64_encode(std::string(static_cast<const char*>(png->data), png->size)));
982	    } catch (const std::exception& error) {
983	        // A preview is derived display data. A failed render or cache write
984	        // must not prevent opening the committed project.
985	        BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
986	    }
987	}
