996	bool ProjectAutosave::save_now()
997	{
998	    try {
999	        adopt_project();
1000	        settle(true); // A failed older write can be retried from the live model.
1001	        m_store->ensure_durable_head();
1002	        observe_document_change();
1003	        if (blank_with_no_work()) {
1004	            m_error.clear();
1005	            m_state = State::Saved;
1006	            return true;
1007	        }
1008	        if (!m_store->head_id().empty() && !m_last_capture_input.empty() &&
1009	            observed_input() == m_last_capture_input) {
1010	            if (m_persistence.document().doc_revision() != m_committed_semantic_revision)
1011	                return persist_document(true);
1012	            m_error.clear();
1013	            m_state = State::Saved;
1014	            return true;
1015	        }
1016	        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
1017	        if (canvas == nullptr || !canvas->is_initialized()) {
1018	            fail("The project canvas is not ready for a durable save");
1019	            return false;
1020	        }
1021	        if (canvas->get_gizmos_manager().is_in_editing_mode(true)) {
1022	            fail("Finish the current tool edit before replacing the project");
1023	            return false;
1024	        }
1025	        return capture(true);
1026	    } catch (const std::exception& error) {
1027	        fail(error.what());
1028	        return false;
1029	    }
1030	}
