1044	std::string ProjectAutosave::pin_current()
1045	{
1046	    if (!save_now())
1047	        return {};
1048	    // A blank startup draft has no automatic version, but it is still the
1049	    // exact before-state of an Agent operation that may add its first object.
1050	    if (m_store->head_id().empty()) {
1051	        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
1052	        if (canvas == nullptr || !canvas->is_initialized()) {
1053	            fail("The project canvas is not ready for a durable save");
1054	            return {};
1055	        }
1056	        if (!capture(true))
1057	            return {};
1058	    }
1059	    const std::string id = m_store->head_id();
1060	    try {
1061	        m_store->pin(id);
1062	    } catch (const std::exception& error) {
1063	        // Pinning writes into the project folder like any save, so a folder
1064	        // that cannot be written is a failed save, reported and retried.
1065	        fail(error.what());
1066	        return {};
1067	    }
1068	    return id;
1069	}
