1089	
1090	bool ProjectAutosave::restore_impl(const std::string& version_id, const std::string& conversation_id)
1091	{
1092	    const bool chat = !conversation_id.empty();
1093	    std::string before_id;
1094	    std::string before_state;
1095	    std::optional<ProjectVersionStore::Materialization> materialized;
1096	    bool replacement_started = false;
1097	    bool marker_written = false;
1098	    try {
1099	        if (!save_now())
1100	            return false;
1101	        if (version_id == m_committed_head && !chat)
1102	            return true;
1103	        before_id = m_committed_head;
1104	        before_state = m_persistence.document().dump();
1105	        m_store->pin(before_id);
1106	        m_store->pin(version_id);
1107	        if (chat) {
1108	            m_store->begin_chat_restore(before_id, version_id, conversation_id);
1109	            marker_written = true;
1110	        }
1111	        if (version_id == before_id) {
1112	            // Resuming on the committed model version moves no model. The
1113	            // document transition still has to be durable before input
1114	            // moves to the resumed chat.
1115	            m_persistence.record_chat_restore(before_state, before_id, version_id, conversation_id);
1116	            if (!persist_document(true))
1117	                throw std::runtime_error(m_error);
1118	            m_store->finish_chat_restore();
1119	            m_persistence.notify_chat_restore_published();
1120	            return true;
1121	        }
1122	        materialized = m_store->materialize(version_id);
1123	        const auto selected = m_store->history();
1124	        const auto version = std::find_if(selected.begin(), selected.end(), [&version_id](const auto& item) {
1125	            return item.id == version_id;
1126	        });
1127	        if (version == selected.end())
1128	            throw std::runtime_error("selected project version is unavailable");
1129	        m_persistence.during_managed_restore([&] {
1130	            replacement_started = true;
1131	            m_plater.reset();
1132	            m_plater.take_snapshot("Restore project version", UndoRedo::SnapshotType::ProjectSeparator);
1133	            auto strategy = LoadStrategy::Restore;
1134	            if (materialized->empty)
