25	std::string default_uuid()
26	{
27	    static std::mt19937_64 engine(std::random_device{}());
28	    std::uniform_int_distribution<std::uint64_t> distribution;
29	    std::ostringstream out;
30	    out << std::hex << distribution(engine) << '-' << distribution(engine);
31	    return out.str();
