34	std::string read_file(const fs::path& path)
35	{
36	    std::ifstream in(path, std::ios::binary);
37	    if (!in.is_open())
38	        return {};
39	    std::stringstream buffer;
40	    buffer << in.rdbuf();
41	    return buffer.str();
42	}
