44	bool write_file(const fs::path& path, const std::string& content)
45	{
46	    std::error_code ec;
47	    fs::create_directories(path.parent_path(), ec);
48	    // Write-then-rename keeps a crash from leaving a truncated state file.
49	    const fs::path temp = path.string() + ".tmp";
50	    {
51	        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
52	        if (!out.is_open())
53	            return false;
54	        out << content;
55	        if (!out.good())
56	            return false;
57	    }
58	    fs::rename(temp, path, ec);
59	    return !ec;
60	}
