62	const char* edit_kind_name(Workspace::EditKind kind)
63	{
64	    switch (kind) {
65	    case Workspace::EditKind::Step: return "step";
66	    case Workspace::EditKind::Undo: return "undo";
67	    case Workspace::EditKind::Redo: return "redo";
68	    case Workspace::EditKind::Setting: return "setting";
69	    case Workspace::EditKind::Preset: return "preset";
70	    }
71	    throw std::logic_error("Unknown workspace edit kind");
72	}
