74	// What put the plan in doubt, as the setup card shows it and the model
75	// reads it, so in words that suit both: what changed and who changed it
76	// ("Filament changed to Generic ABS by hand"). A preset's library suffix
77	// (" @System", " @BBL A1M") is not the person's word and is dropped.
78	std::string plan_doubt_reason(const Workspace::WorkspaceEdit& edit)
79	{
80	    const std::string by = edit.actor == Workspace::EditActor::Person ? "by hand"
81	                         : "by " + (edit.client.empty() ? std::string("another app") : edit.client);
82	    const auto short_preset = [](const std::string& name) { return name.substr(0, name.find(" @")); };
83	    switch (edit.kind) {
84	    case Workspace::EditKind::Preset: {
85	        const std::string what = edit.location == "printer"  ? "Printer"
86	                               : edit.location == "filament" ? "Filament" : "Print settings";
87	        return what + " changed to " + short_preset(edit.label) + " " + by;
88	    }
89	    case Workspace::EditKind::Setting:
90	        return edit.label + " changed" + (edit.after.empty() ? std::string() : " to " + edit.after) + " " + by;
91	    case Workspace::EditKind::Undo: return edit.label.empty() ? "Undone " + by : edit.label + " undone " + by;
92	    case Workspace::EditKind::Redo: return edit.label.empty() ? "Redone " + by : edit.label + " redone " + by;
93	    case Workspace::EditKind::Step: break;
94	    }
95	    return edit.label.empty() ? "The project changed " + by : edit.label + ", " + by;
96	}
