98	// Which reason the card keeps while the plan is in doubt: a setup switch
99	// over the setting edits and steps that follow it, the printer above all.
100	int plan_doubt_weight(const Workspace::WorkspaceEdit& edit)
101	{
102	    if (edit.kind != Workspace::EditKind::Preset)
103	        return 0;
104	    return edit.location == "printer" ? 3 : edit.location == "filament" ? 2 : 1;
105	}
