109	// Shared with each subscription's unsubscribe closure, which outlives neither
110	// the observers nor, through the weak pointer, the persistence that owns them.
111	struct ProjectPersistence::LedgerObservers
112	{
113	    std::uint64_t                                  next_id{1};
114	    std::map<std::uint64_t, std::function<void()>> observers;
115	};
116	
117	Workspace::WorkspaceSubscription ProjectPersistence::subscribe_ledger(std::function<void()> listener)
118	{
119	    const std::uint64_t id = m_ledger_observers->next_id++;
120	    m_ledger_observers->observers.emplace(id, std::move(listener));
121	    std::weak_ptr<LedgerObservers> weak = m_ledger_observers;
122	    return Workspace::WorkspaceSubscription([weak, id]() {
123	        if (auto state = weak.lock())
124	            state->observers.erase(id);
125	    });
126	}
127	
128	void ProjectPersistence::notify_ledger_changed() const
129	{
130	    // Look each observer up just before calling it, so one that unsubscribes
131	    // another, or itself, during dispatch is safe.
132	    std::vector<std::uint64_t> ids;
133	    for (const auto& observer : m_ledger_observers->observers)
134	        ids.push_back(observer.first);
135	    for (const std::uint64_t id : ids) {
136	        const auto found = m_ledger_observers->observers.find(id);
137	        if (found == m_ledger_observers->observers.end())
138	            continue;
139	        const std::function<void()> callback = found->second;
140	        callback();
141	    }
142	}
