144	ProjectPersistence::ProjectPersistence(Workspace::IWorkspace& workspace, Config config)
145	    : m_workspace(workspace), m_config(std::move(config)), m_ledger_observers(std::make_shared<LedgerObservers>())
146	{
147	    if (!m_config.clock)
148	        m_config.clock = default_clock;
149	    if (!m_config.uuid)
150	        m_config.uuid = default_uuid;
151	    if (m_config.in_memory) {
152	        // No project to follow: this session is its own boundary, and it
153	        // needs an identity now because ids are minted from it.
154	        m_document.initialize_identity("p-" + m_config.uuid(), "l-" + m_config.uuid(), m_config.clock());
155	        return;
156	    }
157	    m_subscription = m_workspace.subscribe([this](const Workspace::WorkspaceChanged& change) {
158	        on_workspace_changed(change);
159	    });
160	    m_edit_subscription = m_workspace.subscribe_edits([this](const Workspace::WorkspaceEdit& edit) { on_edit(edit); });
161	}
