163	void ProjectPersistence::on_edit(const Workspace::WorkspaceEdit& edit)
164	{
165	    // The edit belongs to whatever project is really open now.
166	    resolve_pending_boundary();
167	    ChangeEntry entry;
168	    entry.kind   = edit_kind_name(edit.kind);
169	    entry.actor    = edit.actor == Workspace::EditActor::Person ? "person" : "agent";
170	    entry.external = edit.actor == Workspace::EditActor::ExternalTool;
171	    entry.client   = edit.client;
172	    entry.label  = edit.label;
173	    entry.from   = edit.before;
174	    entry.to     = edit.after;
175	    entry.preset   = edit.preset;
176	    entry.key      = edit.key;
177	    entry.location = edit.location;
178	    const ChangeEntry stored = m_document.add_change(std::move(entry), m_config.clock());
179	    // The in-app agent's own edits carry out its plan; they do not put it in
180	    // doubt. A person's edit, Undo and Redo, and an external MCP client's
181	    // edit do.
182	    if (edit.actor != Workspace::EditActor::Agent)
183	        m_document.mark_plan_needs_reassessment(plan_doubt_reason(edit), plan_doubt_weight(edit));
184	    // A paint session is a burst of edits; the owner's pacing timer writes them.
185	    commit();
186	    if (m_change_added)
187	        m_change_added(stored);
188	}
