212	void ProjectPersistence::on_workspace_changed(const Workspace::WorkspaceChanged& change)
213	{
214	    if (m_managed_restore_active)
215	        return;
216	    if (has_reason(change.reasons, WorkspaceChangeReasons::Project)) {
217	        if (!m_attached || m_workspace.auxiliary_data_dir() != m_attached_aux_dir) {
218	            // The new project's directory is already in place: adopt it.
219	            adopt_current_project(/*in_place_reset=*/false);
220	        } else {
221	            // Ambiguous: either an in-place full reset, or a replacement
222	            // whose event was published before the directory moved. Park the
223	            // decision until the directory settles.
224	            m_boundary_pending = true;
225	        }
226	        return;
227	    }
228	    if (heal_if_directory_moved())
229	        return;
230	    if (m_boundary_pending) {
231	        // A later event with the directory still in place means the project
232	        // operation completed without moving it: an in-place reset.
233	        resolve_pending_boundary();
234	    }
235	}
236	
237	bool ProjectPersistence::heal_if_directory_moved()
238	{
239	    // A changed auxiliary directory marks an Orca project boundary. Managed
240	    // state is then adopted from the local store or imported from that
241	    // directory's legacy auxiliary document.
242	    if (!m_attached || m_workspace.auxiliary_data_dir() == m_attached_aux_dir)
243	        return false;
244	    m_boundary_pending = false;
245	    adopt_current_project(/*in_place_reset=*/false);
246	    return true;
247	}
248	
249	void ProjectPersistence::resolve_pending_boundary()
250	{
251	    if (m_managed_restore_active)
252	        return;
253	    if (heal_if_directory_moved())
254	        return;
255	    if (!m_boundary_pending)
256	        return;
257	    m_boundary_pending = false;
258	    adopt_current_project(/*in_place_reset=*/true);
259	}
