261	void ProjectPersistence::during_managed_restore(const std::function<void()>& operation)
262	{
263	    if (m_config.managed_root.empty() || m_managed_restore_active)
264	        throw std::logic_error("managed restore requires an open managed project");
265	    m_managed_restore_active = true;
266	    struct RestoreGuard {
267	        bool& active;
268	        ~RestoreGuard() { active = false; }
269	    } guard{m_managed_restore_active};
270	    operation();
271	}
272	
273	void ProjectPersistence::adopt_current_project(bool in_place_reset)
274	{
275	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
276	    m_attached         = true;
277	    // A calibration generator's own new project: the same project goes on.
278	    if (std::exchange(m_continuing_project, false)) {
279	        m_dirty = true;
280	        flush();
281	        return;
282	    }
283	    m_draft.clear();
284	
285	    if (in_place_reset) {
286	        // A full in-place reset is a new project boundary: earlier state does
287	        // not carry into it.
288	        if (m_config.managed_root.empty()) {
289	            std::error_code ec;
290	            fs::remove_all(jusprin_data_dir(), ec);
291	        }
292	        start_fresh_identity();
293	        return;
294	    }
295	
296	    // An external archive can carry the old auxiliary document. Read it once
297	    // for migration; managed snapshots never write authoritative state there.
298	    const fs::path legacy_state = fs::path(m_attached_aux_dir) / kJusPrinDirName / kStateFileName;
299	    const std::string state_text = read_file(m_config.managed_root.empty() ? fs::path(state_file_path()) : legacy_state);
300	    if (state_text.empty()) {
301	        start_fresh_identity();
302	        return;
303	    }
304	
305	    ProjectStateDocument loaded;
306	    const ProjectStateDocument::LoadResult result = loaded.load(state_text);
307	    if (result == ProjectStateDocument::LoadResult::Corrupt) {
308	        // Keep the unreadable file for inspection, then start over.
309	        std::error_code ec;
310	        fs::rename(legacy_state, legacy_state.string() + ".corrupt", ec);
311	        start_fresh_identity();
312	        return;
313	    }
314	    m_document = std::move(loaded);
315	
316	    if (!m_config.managed_root.empty()) {
317	        // A copied or reopened external archive is an import, even when it
318	        // carries an identity that already has a managed head on this host.
319	        if (fs::exists(fs::path(m_config.managed_root) / m_document.project_id() / "HEAD"))
320	            m_document.fork_identity("p-" + m_config.uuid(), m_config.clock());
321	        // The attachments, and the pictures the chats' records sent.
322	        for (const char* folder : {"attachments", kChatRecordsDir}) {
323	            const fs::path old_folder = fs::path(m_attached_aux_dir) / kJusPrinDirName / folder;
324	            const fs::path local_folder = fs::path(jusprin_data_dir()) / folder;
325	            if (!fs::is_directory(old_folder))
326	                continue;
327	            for (const auto& entry : fs::recursive_directory_iterator(old_folder)) {
328	                const fs::path target = local_folder / fs::relative(entry.path(), old_folder);
329	                if (entry.is_directory())
330	                    fs::create_directories(target);
331	                else if (entry.is_regular_file()) {
332	                    fs::create_directories(target.parent_path());
333	                    fs::copy_file(entry.path(), target, fs::copy_options::overwrite_existing);
334	                }
335	            }
336	        }
337	    }
338	
339	    // A stream or run interrupted by the crash/restart cannot resume.
340	    m_document.normalize_interrupted_state();
341	    if (!m_config.managed_root.empty()) {
342	        m_draft = m_document.draft();
343	    }
344	
345	    m_dirty = true;
346	    flush();
347	    notify_document_replaced();
348	}
