350	void ProjectPersistence::continuing_project(const std::function<void()>& operation)
351	{
352	    if (m_continuing_project)
353	        throw std::logic_error("a project continuation is already armed");
354	    m_continuing_project = true;
355	    struct Disarm {
356	        bool& armed;
357	        ~Disarm() { armed = false; }
358	    } disarm{m_continuing_project};
359	    operation();
360	    resolve_pending_boundary();
