371	void ProjectPersistence::start_fresh_identity()
372	{
373	    m_document = ProjectStateDocument();
374	    m_document.initialize_identity("p-" + m_config.uuid(), "l-" + m_config.uuid(), m_config.clock());
375	    m_dirty = true;
