380	void ProjectPersistence::flush()
381	{
382	    if (m_config.in_memory) {
383	        m_dirty = false;
384	        return;
385	    }
386	    // Never write a stale document across an unresolved project boundary.
387	    resolve_pending_boundary();
388	    if (!m_attached)
389	        return;
390	    if (!m_config.managed_root.empty()) {
391	        // ProjectAutosave publishes the document with a model version or as
392	        // a coalesced current-state write between model edits.
393	        m_dirty = false;
394	        return;
395	    }
396	    write_state_to(jusprin_data_dir());
397	    m_dirty = false;
398	}
