400	void ProjectPersistence::adopt_managed_state(const std::string& state)
401	{
402	    if (m_config.managed_root.empty())
403	        throw std::logic_error("managed state requires a local project store");
404	    ProjectStateDocument loaded;
405	    if (loaded.load(state) == ProjectStateDocument::LoadResult::Corrupt || !loaded.has_identity())
406	        throw std::runtime_error("managed project state is invalid");
407	    loaded.normalize_interrupted_state();
408	    m_document = std::move(loaded);
409	    m_draft = m_document.draft();
410	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
411	    m_attached = true;
412	    m_boundary_pending = false;
413	    m_dirty = false;
414	    notify_document_replaced();
415	}
