423	void ProjectPersistence::record_managed_restore(const std::string& current_state, const std::string& from_version,
424	                                                const std::string& selected_version)
425	{
426	    if (m_config.managed_root.empty())
427	        throw std::logic_error("model restore requires a managed project document");
428	    ProjectStateDocument current;
429	    if (current.load(current_state) == ProjectStateDocument::LoadResult::Corrupt || !current.has_identity())
430	        throw std::runtime_error("current project document is invalid during model restore");
431	    current.normalize_interrupted_state();
432	    ChangeEntry change;
433	    change.kind = "restore";
434	    change.actor = "person";
435	    change.label = "Restored an earlier project version";
436	    change.from = from_version;
437	    change.to = selected_version;
438	    current.add_change(std::move(change), m_config.clock());
439	    // A restore brings back another version's setup whole: no edit outweighs it.
440	    current.mark_plan_needs_reassessment("An earlier model version was restored", 4);
441	    m_document = std::move(current);
442	    m_draft = m_document.draft();
443	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
444	    m_attached = true;
445	    m_boundary_pending = false;
446	    m_dirty = true;
447	    flush();
448	    notify_document_replaced();
449	}
