451	void ProjectPersistence::record_chat_restore(const std::string& current_state,
452	                                              const std::string& from_version,
453	                                              const std::string& selected_version,
454	                                              const std::string& conversation_id)
455	{
456	    if (m_config.managed_root.empty())
457	        throw std::logic_error("chat restore requires a managed project document");
458	    ProjectStateDocument current;
459	    if (current.load(current_state) == ProjectStateDocument::LoadResult::Corrupt || !current.has_identity())
460	        throw std::runtime_error("chat checkpoint is unavailable during restore");
461	    const auto checkpoint = current.chat_checkpoint(conversation_id);
462	    if (!checkpoint || checkpoint->value("versionId", "") != selected_version)
463	        throw std::runtime_error("chat checkpoint changed during restore");
464	    current.normalize_interrupted_state();
465	    // The chat's intent and plan never left it; making it active makes them
466	    // the project's again, with the validity they had when it was left.
467	    if (!current.set_active_conversation(conversation_id) || !current.set_viewed_conversation(conversation_id))
468	        throw std::runtime_error("chat disappeared during restore");
469	    // Resuming on the model already in place restores nothing.
470	    if (from_version != selected_version) {
471	        ChangeEntry change;
472	        change.kind = "restore";
473	        change.actor = "person";
474	        change.label = "Restored this chat's saved project setup";
475	        change.from = from_version;
476	        change.to = selected_version;
477	        current.add_change(std::move(change), m_config.clock());
478	    }
479	    m_document = std::move(current);
480	    m_draft = m_document.draft();
481	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
482	    m_attached = true;
483	    m_boundary_pending = false;
484	    m_dirty = true;
485	    flush();
486	}
