538	void ProjectPersistence::remove_attachment_dir(const std::string& relative_dir)
539	{
540	    if (relative_dir.empty())
541	        return;
542	    if (m_config.in_memory) {
543	        for (auto blob = m_blobs.begin(); blob != m_blobs.end();)
544	            blob = blob->first.rfind(relative_dir, 0) == 0 ? m_blobs.erase(blob) : std::next(blob);
545	        return;
546	    }
547	    if (!m_attached)
548	        return;
549	    // Published semantic versions can still reference an attachment after a
550	    // staged message is removed from the live document. Reachability cleanup
551	    // belongs to the version store, not this mutable conversation surface.
552	    // A chat's record folder is not versioned and goes with the chat.
553	    if (!m_config.managed_root.empty() && relative_dir.rfind(kChatRecordsDir, 0) != 0)
554	        return;
555	    std::error_code ec;
556	    fs::remove_all(fs::path(jusprin_data_dir()) / fs::path(relative_dir), ec);
557	}
