163	std::vector<GcodeHistoryRecorder::Leaving> GcodeHistoryRecorder::leaving(int plate) const
164	{
165	    PartPlateList& plates = m_plater.get_partplate_list();
166	    const Workspace::WorkspaceSnapshot snapshot = m_workspace.snapshot();
167	    std::vector<int> indices;
168	    if (plate == PLATE_ALL_IDX) {
169	        // Every plate that holds a slice went out in the one file.
170	        for (int index = 0; index < plates.get_plate_count(); ++index)
171	            if (plates.get_plate(index)->is_slice_result_valid())
172	                indices.push_back(index);
173	    } else {
174	        indices.push_back(plate == PLATE_CURRENT_IDX ? plates.get_curr_plate_index() : plate);
175	    }
176	
177	    std::vector<Leaving> result;
178	    for (int index : indices) {
179	        PartPlate* part_plate = plates.get_plate(index);
180	        if (part_plate == nullptr || !part_plate->is_slice_result_valid() || part_plate->get_slice_result() == nullptr)
181	            throw std::logic_error("plate " + std::to_string(index) + " left the project without a slice");
182	        const GCodeProcessorResult& sliced = *part_plate->get_slice_result();
183	        // The plate's G-code as the slicer wrote it, as the export_file tool
184	        // copies it: what each route then wraps or post-processes differs.
185	        const std::string path = !sliced.filename.empty() ? sliced.filename : part_plate->get_tmp_gcode_path();
186	        std::optional<Agent::GcodeRecord> facts = Agent::gcode_record(snapshot, std::size_t(index));
187	        if (!facts)
188	            throw std::logic_error("plate " + std::to_string(index) + " is not in the workspace snapshot");
189	        facts->hash = Agent::sha256_file_hex(path);
190	        // The preview's layer count: a move's layer id counts from the first.
191	        for (const GCodeProcessorResult::MoveVertex& move : sliced.moves)
192	            facts->statistics.layer_count = std::max<std::uint64_t>(facts->statistics.layer_count, move.layer_id + 1);
193	        result.push_back({std::move(*facts), path});
194	    }
195	    return result;
196	}
