198	void GcodeHistoryRecorder::record(const std::vector<Leaving>& leaving, GcodeDestination destination,
199	                                  const std::optional<Agent::KeptPackage>& uploaded)
200	{
201	    Agent::ProjectStateDocument& document = m_persistence.document();
202	    if (!document.has_identity())
203	        throw std::logic_error("a G-code left a project that has no identity");
204	    const std::string project_dir = this->project_dir(document.project_id());
205	    const std::string now         = m_persistence.timestamp();
206	    for (const Leaving& item : leaving) {
207	        Agent::keep_gcode_copy(project_dir, item.facts.hash, item.gcode_path);
208	        GcodeDestination kept = destination;
209	        // A package of several plates would print the first again, not this one.
210	        if (uploaded && leaving.size() == 1)
211	            kept.package_hash = Agent::keep_gcode_package(project_dir, item.facts.hash, uploaded->package, uploaded->config);
212	        const std::string id = document.add_gcode_destination(item.facts, kept, now);
213	        await_start(document.project_id(), item.facts.hash, id, kept);
214	    }
215	    m_persistence.commit();
216	    m_persistence.notify_ledger_changed();
217	    if (m_changed)
218	        m_changed();
219	}
