274	bool GcodeHistoryRecorder::intact(const std::string& path, const std::string& expected) const
275	{
276	    const std::filesystem::path file = std::filesystem::u8path(path);
277	    const std::uintmax_t        size = std::filesystem::file_size(file);
278	    const auto                  written = std::filesystem::last_write_time(file);
279	    FileCheck&                  check = m_file_checks[path];
280	    if (check.hash.empty() || check.size != size || check.written != written)
281	        check = {size, written, Agent::sha256_file_hex(path)};
282	    return !expected.empty() && check.hash == expected;
283	}
