309	GcodeHistoryRecorder::PrintAgain GcodeHistoryRecorder::print_again_state(const std::string& project_id,
310	                                                                         const Agent::GcodeRecord& record) const
311	{
312	    const std::string dir  = project_dir(project_id);
313	    const std::string copy = Agent::kept_gcode_copy(dir, record.hash);
314	    if (copy.empty())
315	        return PrintAgain::NotKept;
316	    PresetBundle& presets = *wxGetApp().preset_bundle;
317	    if (presets.use_bbl_network()) {
318	        const std::optional<Agent::KeptPackage> package = Agent::kept_gcode_package(dir, record.hash);
319	        if (!package)
320	            return PrintAgain::NotForThisPrinter;
321	        return intact(package->package, Agent::kept_package_hash(record)) ? PrintAgain::Ready : PrintAgain::Changed;
322	    }
323	    const DynamicPrintConfig& printer = presets.printers.get_edited_preset().config;
324	    if (printer.opt_string("print_host").empty())
325	        return PrintAgain::NoPrinter;
326	    if (!standard_print_host(printer))
327	        return PrintAgain::NotForThisPrinter;
328	    return intact(copy, record.hash) ? PrintAgain::Ready : PrintAgain::Changed;
