331	void GcodeHistoryRecorder::print_again(const std::string& project_id, const std::string& hash)
332	{
333	    const Agent::GcodeRecord record = project_record(project_id, hash);
334	    if (print_again_state(project_id, record) != PrintAgain::Ready)
335	        throw std::logic_error("Print again of G-code " + hash + " was asked for when it is not ready");
336	    const std::string dir = project_dir(project_id);
337	    if (!wxGetApp().preset_bundle->use_bbl_network()) {
338	        send_again_to_print_host(project_id, hash, Agent::kept_gcode_copy(dir, hash), record);
339	        return;
340	    }
341	
342	    // Select Machine in its print-from-storage mode reads the plate, its
343	    // picture and its filaments from a parsed .gcode.3mf, as the printer's
344	    // file browser opens it; the dialog's new-print flag uploads the local
345	    // file instead of printing one on the printer by name.
346	    const Agent::KeptPackage package = *Agent::kept_gcode_package(dir, hash);
347	    DynamicPrintConfig       config;
348	    Model                    model;
349	    PlateDataPtrs            plates;
350	    Semver                   version;
351	    std::ifstream            file(std::filesystem::u8path(package.package), std::ios::binary);
352	    if (!load_gcode_3mf_from_stream(file, &config, &model, &plates, &version) || plates.empty())
353	        throw std::runtime_error("the kept package of G-code " + hash + " could not be read");
354	    std::string name = std::filesystem::u8path(Agent::gcode_display_name(record)).stem().u8string();
355	    m_plater.update_print_required_data(config, model, plates, name + ".gcode.3mf", package.package);
356	    auto* dialog = dynamic_cast<SelectMachineDialog*>(m_plater.get_select_machine_dialog());
357	    if (dialog == nullptr)
358	        throw std::logic_error("OrcaSlicer made no Select Machine dialog for the print-required data");
359	    dialog->set_required_data_new_print(package.config);
360	    m_reprint         = Reprint{project_id, hash, Agent::kept_package_hash(record)};
361	    m_opening_reprint = true;
362	    SimpleEvent open(EVT_PRINT_FROM_SDCARD_VIEW);
363	    m_plater.GetEventHandler()->ProcessEvent(open);
364	    m_opening_reprint = false;
365	    dialog->set_required_data_new_print(std::nullopt);
366	}
