368	void GcodeHistoryRecorder::send_again_to_print_host(const std::string& project_id, const std::string& hash, const std::string& copy,
369	                                                    const Agent::GcodeRecord& record)
370	{
371	    // OrcaSlicer's standard upload dialog, as Plater::send_gcode_legacy shows
372	    // it, for the kept copy rather than an export of the plate.
373	    PrintHostJob upload(&wxGetApp().preset_bundle->printers.get_edited_preset().config);
374	    if (upload.empty())
375	        throw std::logic_error("Print again was offered for a printer with no print host");
376	    wxArrayString groups, storage_paths, storage_names;
377	    {
378	        wxBusyCursor wait;
379	        upload.printhost->get_groups(groups);
380	        try {
381	            upload.printhost->get_storage(storage_paths, storage_names);
382	        } catch (const Slic3r::IOError& error) {
383	            // As OrcaSlicer's own send says it: the host could not be asked.
384	            show_error(&m_plater, error.what(), false);
385	            return;
386	        }
387	    }
388	    std::string name = std::filesystem::u8path(Agent::gcode_display_name(record)).stem().u8string() + ".gcode";
389	    AppConfig&  config = *wxGetApp().app_config;
390	    PrintHostSendDialog dialog(boost::filesystem::path(name), upload.printhost->get_post_upload_actions(), groups, storage_paths,
391	                               storage_names, config.get_bool("open_device_tab_post_upload"));
392	    dialog.init();
393	    if (dialog.ShowModal() != wxID_OK)
394	        return;
395	    config.set_bool("open_device_tab_post_upload", dialog.switch_to_device_tab());
396	    upload.switch_to_device_tab        = dialog.switch_to_device_tab();
397	    upload.upload_data.upload_path     = dialog.filename();
398	    upload.upload_data.post_action     = dialog.post_action();
399	    upload.upload_data.group           = dialog.group();
400	    upload.upload_data.storage         = dialog.storage();
401	    upload.upload_data.extended_info   = dialog.extendedInfo();
402	    // The queue deletes what it uploads: it gets a copy, the kept file stays.
403	    const boost::filesystem::path sent = boost::filesystem::temp_directory_path() /
404	                                         boost::filesystem::unique_path("jusprin-print-again-%%%%%%.gcode");
405	    std::filesystem::copy_file(std::filesystem::u8path(copy), std::filesystem::path(sent.wstring()));
406	    upload.upload_data.source_path = sent;
407	    hook_print_host_queue();
408	    m_reprint = Reprint{project_id, hash, {}};
409	    wxGetApp().printhost_job_queue().enqueue(std::move(upload));
410	}
