1415	void AgentHost::store_file_attachment(AttachmentRecord record, const std::string& bytes, const std::string& correlation_id)
1416	{
1417	    if (bytes.size() > kMaxAttachmentBytes) {
1418	        record.state = "error";
1419	        record.error = AgentError{"too_large", "This file is too large to attach."};
1420	    } else if (record.kind == "unsupported") {
1421	        record.state = "error";
1422	        record.error = AgentError{"unsupported_type", "This file type can't be read by the Agent."};
1423	    } else if ((record.kind == "text" || record.kind == "gcode" || record.kind == "svg") && !is_valid_utf8(bytes)) {
1424	        record.state = "error";
1425	        record.error = AgentError{"not_text", "This file is not readable UTF-8 text."};
1426	    } else if (!m_persistence.write_attachment_blob(record.relative_path(), bytes)) {
1427	        record.state = "error";
1428	        record.error = AgentError{"store_failed", "The attachment could not be stored."};
1429	    } else {
1430	        record.size_bytes = bytes.size();
1431	        if (record.kind == "text" || record.kind == "gcode" || record.kind == "svg") {
1432	            record.preview_text = bytes.size() > kTextPreviewChars ? bytes.substr(0, kTextPreviewChars) : bytes;
1433	        } else if (record.kind == "model") {
1434	            // Models reach the Agent as a native summary, never as bytes. The
1435	            // authoritative import happens when the message is sent (Phase 5
1436	            // import seam); this is the pre-import description.
1437	            record.summary = "3D model \"" + record.original_name + "\" (" + std::to_string(bytes.size()) +
1438	                             " bytes), ready to import into the project.";
1439	        }
1440	        // Images and PDFs are stored as-is; images get an inline preview built
1441	        // on demand from the blob, so nothing large is kept in state.json.
1442	    }
1443	
1444	    m_persistence.document().add_attachment(record, m_persistence.timestamp());
1445	    m_persistence.commit();
1446	    m_persistence.flush();
1447	    send_attachment_updated(record, correlation_id);
1448	}
