1450	void AgentHost::handle_pick_attachment(const std::string& envelope_id, const std::string& payload_json)
1451	{
1452	    const json payload     = json::parse(payload_json);
1453	    const std::string kind = payload.at("kind").get<std::string>();
1454	    // The four kinds the composer's + menu offers, each filtered to exactly
1455	    // the extensions classify_attachment() files under that kind.
1456	    FilePickerRequest request;
1457	    if (kind == "image") {
1458	        request = {"Photo or image", {"png", "jpg", "jpeg", "gif", "webp"}};
1459	    } else if (kind == "model") {
1460	        request.description = "3D model";
1461	        request.extensions.assign(model_extensions().begin(), model_extensions().end());
1462	    } else if (kind == "gcode") {
1463	        request = {"G-code", {"gcode", "g", "gco"}};
1464	    } else if (kind == "pdf") {
1465	        request = {"Document (PDF)", {"pdf"}};
1466	    } else {
1467	        // The page offers a fixed list; any other kind is a broken page.
1468	        throw RuntimeError("jusprin-agent-bridge: pick_attachment names an unknown kind: " + kind);
1469	    }
1470	    if (!m_file_picker) {
1471	        send_bridge_error("unsupported", "This build cannot open a file dialog.", envelope_id);
1472	        return;
1473	    }
1474	    m_file_picker(request, [this, envelope_id](std::vector<std::string> paths) {
1475	        for (const std::string& path : paths) {
1476	            const std::filesystem::path file = std::filesystem::u8path(path);
1477	            AttachmentRecord record;
1478	            record.id            = m_persistence.document().allocate_attachment_id();
1479	            record.original_name = file.filename().u8string();
1480	            record.source        = "picker";
1481	            record.state         = "staged";
1482	            const AttachmentClassification classification = classify_attachment(record.original_name, "");
1483	            record.kind        = classification.kind;
1484	            record.mime        = classification.mime;
1485	            record.stored_name = sanitize_filename(record.original_name);
1486	
1487	            std::error_code size_error;
1488	            const std::uintmax_t size = std::filesystem::file_size(file, size_error);
1489	            std::string bytes;
1490	            if (!size_error && size > kMaxAttachmentBytes) {
1491	                // Refused by its size alone, without reading it.
1492	                record.state = "error";
1493	                record.error = AgentError{"too_large", "This file is too large to attach."};
1494	            } else {
1495	                std::ifstream in(file, std::ios::binary);
1496	                if (in)
1497	                    bytes.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
1498	                if (size_error || !in || in.bad()) {
1499	                    record.state = "error";
1500	                    record.error = AgentError{"unreadable", "The file could not be read."};
1501	                }
1502	            }
1503	            if (record.state == "error") {
1504	                m_persistence.document().add_attachment(record, m_persistence.timestamp());
1505	                m_persistence.commit();
1506	                m_persistence.flush();
1507	                send_attachment_updated(record, envelope_id);
1508	                continue;
1509	            }
1510	            store_file_attachment(std::move(record), bytes, envelope_id);
1511	        }
1512	    });
1513	}
