1515	void AgentHost::handle_remove_attachment(const std::string& envelope_id, const std::string& payload_json)
1516	{
1517	    const json payload   = json::parse(payload_json);
1518	    const std::string id = payload.at("attachmentId").get<std::string>();
1519	    ProjectStateDocument& document = m_persistence.document();
1520	    const std::optional<std::string> removed_dir = document.remove_staged_attachment(id);
1521	    if (!removed_dir) {
1522	        // Already gone or a sent (durable) attachment; report current state so
1523	        // the page reconciles rather than assuming a removal that did not run.
1524	        send_state(envelope_id);
1525	        return;
1526	    }
1527	    m_persistence.remove_attachment_dir(*removed_dir);
1528	    m_persistence.commit();
1529	    m_persistence.flush();
1530	    send_state(envelope_id);
1531	}
