596	void ProjectVersionStore::load_head()
597	{
598	    if (fs::exists(m_root / "HEAD")) {
599	        const json value = json::parse(read_file(m_root / "HEAD"));
600	        require(value.is_object() && value.value("schema", 0) == 1 && value.contains("versions") &&
601	                value["versions"].is_array(), "unsupported current-version index");
602	        m_head_id = value.at("current").get<std::string>();
603	        std::set<std::string> seen;
604	        for (const json& item : value["versions"]) {
605	            const std::string id = item.get<std::string>();
606	            require(safe_component(id) && seen.insert(id).second, "invalid committed-version index");
607	            m_committed_ids.push_back(id);
608	        }
609	        require(!m_committed_ids.empty() && m_committed_ids.back() == m_head_id,
610	                "current version does not match committed-version index");
611	        require(safe_component(m_head_id), "invalid current version id");
612	        const Version version = read_version(m_head_id);
613	        for (const std::string& id : m_committed_ids)
614	            if (fs::exists(version_dir(id) / "manifest.json"))
615	                m_history.push_back(read_version(id));
616	        m_last_metadata_digest = archive_digest(version_dir(m_head_id) / "metadata.3mf");
617	        m_last_regions = version.regions;
618	        for (const ObjectResource& object : version.objects)
619	            m_last_resources[object.object_id] = object;
620	    }
621	    if (fs::exists(m_root / "current-state.json")) {
622	        const json current = json::parse(read_file(m_root / "current-state.json"));
623	        require(current.is_object() && current.value("schema", 0) == 2 && current.contains("state") &&
624	                current["state"].is_object() && current["state"].contains("project") &&
625	                current["state"]["project"].is_object(), "current project document index is invalid");
626	        require(current["state"]["project"].value("projectId", std::string()) == m_project_id,
627	                "current project document does not match the project");
628	        m_last_semantic_state = current["state"].dump(2);
629	        m_document_durable = true;
630	    }
631	    if (!m_head_id.empty())
632	        require(!m_last_semantic_state.empty(), "current project document is missing");
633	    if (!m_last_semantic_state.empty())
634	        validate_attachments(m_root, m_last_semantic_state);
635	}
