854	ProjectVersionStore::Materialization ProjectVersionStore::materialize(const std::string& version_id) const
855	{
856	    const Version version = read_version(version_id);
857	    Materialization result;
858	    result.directory = m_root / "materialized" / new_id();
859	    result.metadata = result.directory / ".3mf";
860	    result.absent_original = result.directory / "source-unavailable.3mf";
861	    result.empty = version.objects.empty();
862	    result.regions = version.regions;
863	    fs::create_directories(result.directory / "3D" / "Objects");
864	    const fs::path stored_metadata = version_dir(version_id) / "metadata.3mf";
865	    validate_metadata(stored_metadata, version);
866	    fs::copy_file(stored_metadata, result.metadata);
867	    result.semantic_state = m_last_semantic_state;
868	    require(json::parse(result.semantic_state).is_object(), "current project document is invalid");
869	    validate_attachments(m_root, result.semantic_state);
870	    for (const ObjectResource& object : version.objects) {
871	        const fs::path source = resource_path(object.resource.id);
872	        validate_resource(source, object.resource.entry, object.facets);
873	        copy_or_relabel(source, object.resource.entry, result.directory / fs::u8path(object.entry), object.entry);
874	    }
875	    return result;
876	}
